const CH = {"pages::about::our-mission::content": {"old": "Nuestra misión es guiar a las personas en un viaje de comprensión y crecimiento cognitivo. Aprovechando las profundas ideas de nuestros tests de IQ y reportes meticulosamente elaborados, buscamos iluminar las fortalezas y competencias únicas que definen el perfil de inteligencia de cada individuo. Creemos en el poder transformador del autoconocimiento y su capacidad para mejorar las relaciones personales y profesionales, promover el bienestar mental y fomentar una vida plena.", "new": "Nuestra misión es guiar a las personas en un viaje de comprensión y crecimiento cognitivo. Aprovechando las profundas ideas de nuestros tests de IQ y informes meticulosamente elaborados, buscamos iluminar las fortalezas y competencias únicas que definen el perfil de inteligencia de cada individuo. Creemos en el poder transformador del autoconocimiento y su capacidad para mejorar las relaciones personales y profesionales, promover el bienestar mental y fomentar una vida plena."}, "payments::members::members-scripts::please-enter-your-current-password": {"old": "Por favor ingresa tu contraseña actual", "new": "Por favor, introduce tu contraseña actual"}, "payments::members::members-account::the-email-address-you-entered": {"old": "La dirección de correo electrónico que ingresaste ya está en uso.", "new": "La dirección de correo electrónico que has introducido ya está en uso."}, "payments::members::members-account::the-current-password-you-entered": {"old": "La contraseña actual que ingresaste es incorrecta.", "new": "La contraseña actual que has introducido es incorrecta."}};
const names = Object.keys(CH).join(',');
return [{ json: { CH, url: 'https://api.lokalise.com/api2/projects/185916266aa3d6649ca6f7.57851232/keys?include_translations=1&disable_references=1&filter_translation_lang_ids=1056&limit=500&filter_keys=' + encodeURIComponent(names) } }];

const MODE = 'all'; // dry | one | all
const cfg = $('Config').first().json; const CH = cfg.CH;
const body = $input.first().json;
if (!Array.isArray(body.keys)) throw new Error('no keys array: ' + JSON.stringify(body).slice(0, 300));
const found = {}, missing = [], mismatch = [], put = [];
for (const k of body.keys) {
  const kn = k.key_name || {}; const n = kn.web || kn.other || kn.ios || kn.android;
  if (!CH[n]) continue;
  const t = (k.translations || []).find(x => x.language_iso === 'es');
  let cur = t ? t.translation : ''; if (cur && typeof cur === 'object') cur = JSON.stringify(cur);
  found[n] = 1;
  if (cur !== CH[n].old) { mismatch.push({ key: n, cur, expected: CH[n].old }); continue; }
  put.push({ key_id: k.key_id, translations: [{ language_iso: 'es', translation: CH[n].new, is_reviewed: false }] });
}
for (const n of Object.keys(CH)) if (!found[n]) missing.push(n);
const sel = MODE === 'one' ? put.slice(0, 1) : (MODE === 'all' ? put : []);
if (sel.length === 0) return [];
return [{ json: { mode: MODE, planned: Object.keys(CH).length, ok: put.length, sending: sel.length, missing, mismatch, body: { keys: sel } } }];

const pages = [$('Gloss p1').first().json.body, $('Gloss p2').first().json.body];
const terms = {};
for (const b of pages) { const arr = (b && (b.data || b.terms)) || []; for (const t of arr) terms[t.id] = t; }
const hits = Object.values(terms).filter(t => (t.term || '').trim().toLowerCase() === 'try again');
if (hits.length !== 1) throw new Error('Try again terms found: ' + hits.length + ' of ' + Object.keys(terms).length);
const g = hits[0]; const DROP = new Set([759, 1057, 10010]);
const NEW = 'Intentar de nuevo'; const DESC = 'Botones: infinitivo, según la guía de estilo.';
const tr = (g.translations || []).filter(t => !DROP.has(t.langId)).map(t => ({ langId: t.langId, translation: t.langId === 1056 ? NEW : t.translation, description: t.langId === 1056 ? DESC : (t.description || '') }));
if (!tr.some(t => t.langId === 1056)) tr.push({ langId: 1056, translation: NEW, description: DESC });
return [{ json: { total_terms: Object.keys(terms).length, snapshot: g, body: { terms: [{ id: g.id, term: g.term, description: g.description, caseSensitive: g.caseSensitive, translatable: g.translatable, forbidden: g.forbidden, translations: tr, tags: g.tags }] } } }];
